 import { gsap } from 'gsap';
import { MeshPhysicalNodeMaterial, MeshBasicNodeMaterial } from 'three/webgpu';
import { color, mix, smoothstep, uv, texture, positionLocal, length, sin, fract, dot, vec2 } from 'three/tsl';

export default function createNode(config, ctx) {
  const THREE = ctx.THREE;
  const {
    Group, Mesh, TorusKnotGeometry, CylinderGeometry, PlaneGeometry, CircleGeometry,
    SpotLight, PointLight, Color, Vector3, Box3, RepeatWrapping, NoColorSpace
  } = THREE;

  const root = new Group();

  // --- lights ---------------------------------------------------------------
  const key = new SpotLight(new Color('#e8ecf2'), 1.2);
  key.position.set(3, 5, 5);
  key.angle = Math.PI / 6;
  key.penumbra = 0.3;
  key.target.position.set(0, 0.4, 0);
  root.add(key);
  root.add(key.target);

  const rim = new PointLight(new Color('#ff2a38'), 0.8);
  rim.position.set(-3, 2, -2);
  root.add(rim);

  const fill = new PointLight(new Color('#e8ecf2'), 0.35);
  fill.position.set(0, 3, 1.5);
  root.add(fill);

  // --- backdrop gradient ----------------------------------------------------
  const backdropGeo = new PlaneGeometry(7, 6);
  const backdropMat = new MeshBasicNodeMaterial();
  const t = uv().y;
  const cBack = color('#0b0b10');
  const cMid = color('#101017');
  const cTop = color('#16161d');
  backdropMat.colorNode = mix(mix(cBack, cMid, smoothstep(0.0, 0.7, t)), cTop, smoothstep(0.7, 1.0, t));
  const backdrop = new Mesh(backdropGeo, backdropMat);
  backdrop.position.z = -3;
  root.add(backdrop);

  // --- contact shadow -------------------------------------------------------
  const shadowGeo = new CircleGeometry(1.5, 64);
  const shadowMat = new MeshBasicNodeMaterial({ transparent: true, depthWrite: false });
  const d = length(positionLocal.xz);
  shadowMat.colorNode = color('#000000');
  shadowMat.opacityNode = smoothstep(1.5, 1.1, d).mul(0.6);
  const contactShadow = new Mesh(shadowGeo, shadowMat);
  contactShadow.rotation.x = -Math.PI / 2;
  contactShadow.position.y = -0.36;
  contactShadow.renderOrder = 1000;
  root.add(contactShadow);

  // --- pedestal -------------------------------------------------------------
  const pedestalMat = new MeshPhysicalNodeMaterial({
    color: new Color('#14141a'),
    roughness: 0.7,
    metalness: 0.35,
    clearcoat: 0.1,
    clearcoatRoughness: 0.4,
    envMapIntensity: 0.7
  });
  const pedestalGeo = new CylinderGeometry(1.1, 1.1, 0.5, 64);
  const pedestal = new Mesh(pedestalGeo, pedestalMat);
  pedestal.position.y = -0.6;
  root.add(pedestal);

  const chamferGeo = new THREE.TorusGeometry(1.1, 0.03, 16, 64);
  const chamfer = new Mesh(chamferGeo, pedestalMat);
  chamfer.rotation.x = Math.PI / 2;
  chamfer.position.y = -0.35;
  root.add(chamfer);

  // --- torus knot material study --------------------------------------------
  const knotGroup = new Group();
  knotGroup.position.set(0, 0.4, 0);
  root.add(knotGroup);

  const segments = ctx.tier === 'T0' ? 160 : 220;
  const knotGeo = new TorusKnotGeometry(0.7, 0.22, segments, 36);
  const knotMat = new MeshPhysicalNodeMaterial({
    color: new Color('#c0c4ca'),
    metalness: 0.55,
    roughness: 0.55,
    clearcoat: 0.22,
    clearcoatRoughness: 0.35,
    envMapIntensity: 0.7
  });
  if ('anisotropy' in knotMat) knotMat.anisotropy = 0.9;
  if ('anisotropyRotation' in knotMat) knotMat.anisotropyRotation = Math.PI / 2;

  const knot = new Mesh(knotGeo, knotMat);
  knotGroup.add(knot);

  let roughnessTex = null;

  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      roughnessTex = tex;
      roughnessTex.colorSpace = NoColorSpace;
      roughnessTex.wrapS = RepeatWrapping;
      roughnessTex.wrapT = RepeatWrapping;
      roughnessTex.needsUpdate = true;

      knotMat.bumpMap = roughnessTex;
      knotMat.bumpScale = 0.15;

      const roughnessTexNode = texture(roughnessTex);
      const jitter = fract(sin(dot(uv().mul(10), vec2(12.9898, 78.233))).mul(43758.5453)).mul(0.02);
      knotMat.roughnessNode = roughnessTexNode.mul(0.9).mul(0.55).add(jitter);

      knotMat.needsUpdate = true;
    });
  }

  // --- text -----------------------------------------------------------------
  const textRoot = new Group();
  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];

  for (const item of items) {
    const role = item.role || 'body';
    const str = String(item.text || '');
    if (!str) continue;

    if (role === 'headline') {
      const h = ctx.fontAtlas.createText(str, {
        fontSize: item.typography?.fontSize ?? 68,
        color: '#e8ecf2',
        align: 'center',
        letterSpacingPx: -0.34
      });
      const box = new Box3().setFromObject(h);
      const hgt = box.max.y - box.min.y;
      if (hgt > 0) h.scale.setScalar(0.34 / hgt);
      h.position.y = -0.8;
      textRoot.add(h);
    } else if (role === 'caption') {
      const c = ctx.fontAtlas.createText(str, {
        fontSize: item.typography?.fontSize ?? 18,
        color: '#e8ecf2',
        align: 'center',
        letterSpacingPx: 1.44
      });
      const box = new Box3().setFromObject(c);
      const hgt = box.max.y - box.min.y;
      if (hgt > 0) c.scale.setScalar(0.09 / hgt);
      c.position.y = -1.2;
      textRoot.add(c);
    } else {
      const o = ctx.fontAtlas.createText(str, {
        fontSize: item.typography?.fontSize ?? 18,
        color: '#e8ecf2',
        align: 'center'
      });
      const box = new Box3().setFromObject(o);
      if (box.max.y - box.min.y > 0) o.scale.setScalar(0.13 / (box.max.y - box.min.y));
      o.position.y = -1.6;
      textRoot.add(o);
    }
  }
  root.add(textRoot);

  // --- cinematic primitives -----------------------------------------------
  const primApis = [];
  const primList = config.cinematicPrimitives || [];
  for (const prim of primList) {
    const apply = ctx.primitives?.[prim.name];
    if (!apply) continue;
    const target = prim.name === 'orbit' ? knot : root;
    const params = { ...prim.params, trigger: prim.trigger };
    primApis.push(apply(target, params));
  }

  // --- motion ---------------------------------------------------------------
  const introTl = gsap.timeline();
  introTl.from(knotGroup.position, { y: 0.8, duration: 0.8, ease: 'power3.out' }, 0);
  introTl.from(knot.scale, { x: 0.95, y: 0.95, z: 0.95, duration: 0.9, ease: 'power4.out' }, 0);
  introTl.from([pedestal.position, chamfer.position], { y: '-=0.2', duration: 0.7, ease: 'power2.out', stagger: 0.05 }, 0);
  introTl.from(textRoot.position, { y: '-=0.2', duration: 0.5, ease: 'power2.out' }, 0.2);

  // --- runtime contract -----------------------------------------------------
  root.userData.handlers = {};

  root.userData.cleanup = () => {
    introTl.kill();
    primApis.forEach((p) => p?.cleanup?.());
    root.traverse((obj) => {
      if (obj.geometry) obj.geometry.dispose();
      if (obj.material) {
        if (Array.isArray(obj.material)) {
          obj.material.forEach((m) => m.dispose?.());
        } else {
          obj.material.dispose?.();
        }
      }
    });
    if (roughnessTex && roughnessTex.dispose) roughnessTex.dispose();
  };

  return root;
}
